SELECT , b.skill_name, b.file_info_id, b.remark AS "skillDesc", u1.real_name AS "creatorName", u2.real_name AS "auditUserName", c.space_name FROM bt_skill_publish_apply a JOIN bt_agent_skill b ON b.skill_id = a.skill_id AND b.status_cd = '00A' LEFT JOIN bt_workspace c ON c.space_id = a.space_id LEFT JOIN bt_user u1 ON u1.user_id = a.creator_id LEFT JOIN bt_user u2 ON u2.user_id = a.audit_user_id WHERE a.status_cd = '00A'
AND a.audit_status = #{params.auditStatus}
AND b.skill_name LIKE #{params.searchContent}
ORDER BY a.created_time DESC

SELECT a.apply_id, a.skill_id, a.apply_content, a.created_time, a.space_id, a.audit_status, a.audit_content,
       b.skill_name
FROM bt_skill_publish_apply a
JOIN bt_agent_skill b ON b.skill_id = a.skill_id AND b.status_cd = '00A'
WHERE a.status_cd = '00A'
  AND a.creator_id = #{params.creatorId}

  AND a.audit_status = #{params.auditStatus}


  AND b.skill_name LIKE #{params.searchContent}

ORDER BY a.created_time DESC

